class Solution {
    public boolean isDecomposable(String s) {
        boolean hasTwo = false;
        int i = 0, n = s.length();
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            int len = j - i;
            int rem = len % 3;
            if (rem == 2) {
                if (hasTwo) return false;
                hasTwo = true;
            } else if (rem != 0) {
                return false;
            }
            i = j;
        }
        return hasTwo;
    }
}

var isDecomposable = function(s) {
  let hasTwo = false;
  let i = 0, n = s.length;
  while (i < n) {
    let j = i;
    while (j < n && s[j] === s[i]) j++;
    const len = j - i;
    const rem = len % 3;
    if (rem === 2) {
      if (hasTwo) return false;
      hasTwo = true;
    } else if (rem !== 0) {
      return false;
    }
    i = j;
  }
  return hasTwo;
};
